item.stdout:
            }
            hasher.update(&buffer[..read]);
            length = length.checked_add(read as u64).ok_or_else(|| {
                std::io::Error::new(std::io::ErrorKind::InvalidData, "artifact exceeds supported length")
            })?;
        }
        Ok((Self(format!("{:x}", hasher.finalize())), length))
    }
}

