}

fn validated_registry_key(raw: String) -> Result<RegistryKey, ReleaseOperationError> {
    if raw.is_empty()
        || raw.len() > 128
        || !raw
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err(ReleaseOperationError::MalformedRegistryKey { raw });
    }
    Ok(RegistryKey(raw))
}

/// An immutable, canonical authorization intent. Graph owns its construction.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleaseIntentV1 {
    pub schema_version: u8,
    pub decision: ReleaseDecisionV1,
    pub snapshot: ReleaseInputSnapshotV1,
    pub trust_profile: ExecutionTrustProfileV1,
    pub operations: Vec<ReleaseOperation>,
    pub artifact_slots: Vec<ArtifactSlotId>,
    digest: IntentDigest,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseIntentV1Wire {
    schema_version: u8,
    decision: ReleaseDecisionV1,
    snapshot: ReleaseInputSnapshotV1,
    trust_profile: ExecutionTrustProfileV1,
    operations: Vec<ReleaseOperation>,
    artifact_slots: Vec<ArtifactSlotId>,
    digest: IntentDigest,
}

impl<'de> Deserialize<'de> for ReleaseIntentV1 {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseIntentV1Wire::deserialize(deserializer)?;
        check_schema_version::<D::Error>(wire.schema_version, Self::SCHEMA_VERSION, "release intent")?;
        check_schema_version::<D::Error>(
            wire.decision.schema_version,
            ReleaseDecisionV1::SCHEMA_VERSION,
            "release intent",
        )?;
        check_schema_version::<D::Error>(
            wire.snapshot.schema_version,
            ReleaseInputSnapshotV1::SCHEMA_VERSION,
            "release intent",
        )?;
        if wire.snapshot.packages.windows(2).any(|pair| pair[0] >= pair[1]) {
            return Err(serde::de::Error::custom("release input packages are not canonical"));
        }
        let intent = Self::new(
            wire.decision,
            wire.snapshot,
            wire.trust_profile,
            wire.operations,
            wire.artifact_slots,
        )
        .map_err(serde::de::Error::custom)?;
        if intent.digest != wire.digest {
            return Err(serde::de::Error::custom(
                "release intent digest does not match canonical content",
            ));
        }
        Ok(intent)
    }
}

impl ReleaseIntentV1 {
    pub const SCHEMA_VERSION: u8 = 1;

    pub fn new(
        decision: ReleaseDecisionV1,
        snapshot: ReleaseInputSnapshotV1,
        trust_profile: ExecutionTrustProfileV1,
        operations: Vec<ReleaseOperation>,
        mut artifact_slots: Vec<ArtifactSlotId>,
    ) -> Result<Self, ReleaseIntentError> {
        if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit)
            || !matches!(snapshot.source, SourceIdentity::GitCommit { .. })
        {
            return Err(ReleaseIntentError::UnsupportedTrustProfile);
        }
        validate_operations(&operations)?;
        validate_operation_roster(&decision, &operations)?;
        artifact_slots.sort();
        if artifact_slots.windows(2).any(|pair| pair[0] == pair[1]) {
            return Err(ReleaseIntentError::DuplicateArtifactSlot);
        }
        if artifact_slots.iter().any(|slot| {
            !decision
                .entries
                .iter()
                .any(|entry| entry.package == slot.package && entry.target_version == slot.version)
        }) {
            return Err(ReleaseIntentError::ArtifactSlotOutsideDecision);
        }
        validate_artifact_upload_roster(&operations, &artifact_slots)?;
        let digest = digest_intent(&decision, &snapshot, trust_profile, &operations, &artifact_slots);
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            decision,
            snapshot,
            trust_profile,
            operations,
            artifact_slots,
            digest,
        })
    }

    pub fn digest(&self) -> &IntentDigest {
        &self.digest
    }
}

fn digest_intent(
    decision: &ReleaseDecisionV1,
    snapshot: &ReleaseInputSnapshotV1,
    trust_profile: ExecutionTrustProfileV1,
    operations: &[ReleaseOperation],
    artifact_slots: &[ArtifactSlotId],
) -> IntentDigest {
    let mut transcript = CanonicalTranscript::intent_v1();
    transcript.push_bytes("schema", [ReleaseIntentV1::SCHEMA_VERSION]);
    transcript.push_str("decision", decision.digest.as_str());
    transcript.push_str("snapshot", snapshot.digest().as_str());
    transcript.push_str(
        "trust-profile",
        match trust_profile {
            ExecutionTrustProfileV1::GitCommit => "git-commit",
            ExecutionTrustProfileV1::HermeticContent => "hermetic-content",
        },
    );
    for operation in operations {
        transcript.push_str("operation", &operation_id_text(&operation.id));
        for prerequisite in &operation.prerequisites {
            transcript.push_str("prerequisite", &operation_id_text(prerequisite));
        }
    }
    for slot in artifact_slots {
        transcript.push_str("artifact-slot.package", &slot.package.to_string());
        transcript.push_str("artifact-slot.version", slot.version.render());
        transcript.push_str("artifact-slot.platform", &slot.platform);
        transcript.push_str("artifact-slot.asset", &slot.asset_name);
        transcript.push_str(
            "artifact-slot.repository",
            &slot.attestation_policy.repository.as_slug(),
        );
        transcript.push_str("artifact-slot.workflow-path", &slot.attestation_policy.workflow_path);
        transcript.push_str(
            "artifact-slot.workflow-commit",
            slot.attestation_policy.workflow_commit.as_str(),
        );
    }
    IntentDigest::from_transcript(&transcript)
}

fn validate_operation_roster(
    decision: &ReleaseDecisionV1,
    operations: &[ReleaseOperation],
) -> Result<(), ReleaseIntentError> {
    let roster = &decision.entries;
    for operation in operations {
        if !roster
            .iter()
            .any(|entry| entry.package == operation.id.package && entry.target_version == operation.id.version)
        {
            return Err(ReleaseIntentError::OperationOutsideDecision {
                id: Box::new(operation.id.clone()),
            });
        }
    }
    Ok(())
}

fn validate_artifact_upload_roster(
    operations: &[ReleaseOperation],
    artifact_slots: &[ArtifactSlotId],
) -> Result<(), ReleaseIntentError> {
    let mut uploads = operations
        .iter()
        .filter_map(|operation| operation.id.role.artifact_slot())
        .collect::<Vec<_>>();
    uploads.sort();
    if uploads.iter().copied().ne(artifact_slots.iter()) {
        return Err(ReleaseIntentError::MismatchedArtifactUploadRoster);
    }
    Ok(())
}

fn operation_id_text(id: &ReleaseOperationId) -> String {
    let role = match &id.role {
        ReleaseOperationRole::RegistryPublish { registry } => format!(
            "publish:{}:{}",
            registry.registry_key().as_str(),
            registry.binding_digest().as_str()
        ),
        ReleaseOperationRole::Tag => "tag".to_string(),
        ReleaseOperationRole::ForgeRelease => "forge-release".to_string(),
        ReleaseOperationRole::ArtifactUpload { slot } => format!(
            "artifact-upload:{}:{}:{}:{}:{}:{}",
            slot.platform,
            slot.asset_name,
            slot.attestation_policy.repository,
            slot.attestation_policy.workflow_path,
            slot.attestation_policy.workflow_commit.as_str(),
            slot.version.render(),
        ),
    };
    format!("{}|{}|{}", id.package, role, id.version.render())
}

fn validate_operations(operations: &[ReleaseOperation]) -> Result<(), ReleaseIntentError> {
    let mut ids = BTreeSet::new();
    for operation in operations {
        if !ids.insert(operation.id.clone()) {
            return Err(ReleaseIntentError::DuplicateOperation {
                id: Box::new(operation.id.clone()),
            });
        }
            });
        }
        Ok(())
    }
}

/// Builds a release intent from a fresh root-bound observation.
pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    decision: &ReleaseDecisionV1,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<ReleaseIntentV1, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let source = observe_source(&workspace, trust_profile)?;
    let intent = derive_release_intent(&workspace, decision, source.clone(), trust_profile)?;

    // Recheck after all input reads. A concurrent edit or checkout cannot be
    // authorized merely because it happened after the first check.
    if observe_source(&workspace, trust_profile)? != source {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::source_identity_changed(),
        });
    }
    Ok(intent)
}

/// Re-observes root, config, package discovery, manifests, Git evidence, and
/// the exact operation DAG before creating an opaque authorization capability.
pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    validate_release_intent_with_state_directory(root, locator, runner, None, received)
}

/// Validates an intent while placing its workspace lock under an explicit
/// caller-owned state directory.
///
/// CI callers that supply an explicit durable state file must use its parent
/// here as well.  Otherwise validation would still depend on the runner's
/// implicit platform state location, defeating hermetic job handoff.
pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    state_directory: Option<&Path>,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let initial_trust = observe_git_trust(&workspace, received.trust_profile)?;
    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
    let trust = observe_git_trust(&workspace, received.trust_profile)?;
    if trust != initial_trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::trust_evidence_changed(),
        });
    }
    let source = source_from_trust(&trust);
    let (expected, prepared) =
        derive_release_intent_with_prepared(&workspace, &received.decision, source.clone(), received.trust_profile)?;
    let final_trust = observe_git_trust(&workspace, received.trust_profile)?;
    if expected != received || final_trust != trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }

    Ok(ValidatedReleaseIntent {
        prepared: PreparedReleaseInputs {
            root,
            source,
            trust: final_trust,
            git_remote: prepared.git_remote,
            _lock: lock,
            operations: prepared.operations,
        },
        intent: received,
        runner,
    })
}

fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
        path: root.to_path_buf(),
        message: error.to_string(),
    })
}

fn observe_source<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<SourceIdentity, GraphError> {
    Ok(source_from_trust(&observe_git_trust(workspace, trust_profile)?))
}

fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<GitCommitTrustEvidence, GraphError> {
    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
        return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
    }
    let evidence = workspace.git_access().observe_git_commit_trust()?;
    if evidence.canonical_root() != workspace.root {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
        });
    }
    if evidence.head_disposition() != GitHeadDisposition::Detached {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::DetachedHead,
        });
    }
    Ok(evidence)
}

fn source_from_trust(evidence: &GitCommitTrustEvidence) -> SourceIdentity {
    SourceIdentity::GitCommit {
        sha: evidence.head().clone(),
    }
}

impl ValidatedReleaseIntent<'_> {
    /// Dispatches exactly one graph-private operation prepared during fresh
    /// validation. This is intentionally the only production effect path: it
    /// never accepts a path, endpoint, tag, package name, or version from a
    /// caller.
    pub(crate) fn dispatch_prepared(
        &self,
        permit: &ApplyPermit,
        id: &ReleaseOperationId,
    ) -> Result<OperationOutcome, GraphError> {
        let operation = self
            .prepared
            .operations
            .get(id)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
            })?;
        match operation {
            PreparedOperation::RegistryPublish { .. } => self.dispatch_registry(permit, id, operation),
            PreparedOperation::Tag {
                name,
                target,
                annotation,
            } => self.dispatch_tag(permit, name, target, annotation),
            PreparedOperation::ForgeRelease { tag } => self.dispatch_forge_release(tag),
        }
    }

    fn dispatch_registry(
        &self,
        _permit: &ApplyPermit,
        id: &ReleaseOperationId,
        prepared: &PreparedOperation,
    ) -> Result<OperationOutcome, GraphError> {
        let PreparedOperation::RegistryPublish {
            package_dir,
            package_name,
            version,
            registry,
            npm_access,
            npm_tag,
        } = prepared
        else {
            return Err(GraphError::ReleaseInvariant {
                detail: format!("dispatch_registry: operation `{id:?}` is not a RegistryPublish"),
            });
        };
        let output = match id.package.ecosystem() {
            Ecosystem::Cargo => {
                let registry_key = (registry.key.as_str() != RegistryKey::CRATES_IO).then(|| registry.key.as_str());
                let argv = registry_argv::cargo_publish_argv(
                    &self.prepared.root,
                    package_dir,
    let malformed = |detail: String| GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(ToString::to_string).collect(),
        failure: CommandFailure::MalformedOutput { detail },
    };
    let (headers, body) = stdout
        .rsplit_once("\r\n\r\n")
        .or_else(|| stdout.rsplit_once("\n\n"))
        .ok_or_else(|| malformed("response has no blank line separating headers from body".to_string()))?;
    let status_line = headers
        .lines()
        .rev()
        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))
        .ok_or_else(|| malformed("response headers contain no HTTP status line".to_string()))?;
    let status = status_line
        .split_whitespace()
        .nth(1)
        .ok_or_else(|| malformed(format!("HTTP status line has no status code: {status_line:?}")))?
        .parse::<u16>()
        .map_err(|error| malformed(format!("HTTP status code is not a valid number: {error}")))?;
    Ok((status, body))
}

fn derive_release_intent<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: SourceIdentity,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<ReleaseIntentV1, GraphError> {
    let (snapshot, operations, _, _) = derive_release_inputs(workspace, decision, source)?;
    Ok(ReleaseIntentV1::new(
        decision.clone(),
        snapshot,
        trust_profile,
        operations,
        vec![],
    )?)
}

fn derive_release_intent_with_prepared<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: SourceIdentity,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<(ReleaseIntentV1, PreparedDerivation), GraphError> {
    let (snapshot, operations, prepared, git_remote) = derive_release_inputs(workspace, decision, source)?;
    let intent = ReleaseIntentV1::new(decision.clone(), snapshot, trust_profile, operations, vec![])?;
    Ok((
        intent,
        PreparedDerivation {
            operations: prepared,
            git_remote,
        },
    ))
}

fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: SourceIdentity,
) -> Result<DerivedReleaseInputs, GraphError> {
    let mut package_inputs = Vec::new();

    let mut selected = BTreeMap::new();
    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
    for package in workspace.graph.packages() {
        // One canonical manifest per ecosystem is the expected shape, but
        // dedup defensively -- `release_package_ids` maps every canonical
        // manifest, and two manifests sharing an ecosystem would otherwise
        // select/push the same identity twice.
        for id in super::release_decision::release_package_ids(package)?
            .into_iter()
            .collect::<BTreeSet<_>>()
        {
            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
                selected.insert(id.clone(), (package, entry.target_version.clone()));
                package_ids.entry(package.id.clone()).or_default().push(id);
            }
        }
    }
    for entry in &decision.entries {
        let id = &entry.package;
        if !selected.contains_key(id) {
            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
        }
    }

    let requires_git_remote = selected.values().any(|(package, _)| {
        package
            .publish_to
            .iter()
            .any(|target| !matches!(target, PublishTarget::None))
    });
    let git_remote = requires_git_remote
        .then(|| prepared_git_remote(&workspace.root, workspace.runner))
        .transpose()?;

    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
    let mut prepared = BTreeMap::<ReleaseOperationId, PreparedOperation>::new();
    let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
    let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();

    // First construct leaves so dependency prerequisites can refer only to
    // exact selected release identities, never PackageId's wildcard matcher.
    for (id, (package, version)) in &selected {
        let produces_tag = package
            .publish_to
            .iter()
            .any(|target| !matches!(target, PublishTarget::None));
        let fingerprint = package_fingerprint(
            workspace,
            id,
            package,
            version,
            produces_tag.then_some(git_remote.as_ref()).flatten(),
        )?;
        package_inputs.push(ReleasePackageInputV1 {
            package: id.clone(),
            fingerprint,
        });

        let mut publishes = Vec::new();
        for target in &package.publish_to {
            if target.ecosystem() == Some(id.ecosystem()) {
                let registry_key = target.registry_key().expect("registry target has registry key");
                let binding = prepared_registry_binding(workspace, target)?;
                let operation = ReleaseOperation::registry_publish(
                    id.clone(),
                    version.clone(),
                    RegistryBindingId::new(registry_key.as_str(), binding.identity.clone())?,
                    Vec::new(),
                )?;
                // A durable registry operation must have one exact endpoint
                // binding. The model-level operation identity currently has
                // only a registry key, so reject a second target that would
                // collapse to the same operation until the typed binding
                // identity is added there.
                if prepared.contains_key(operation.id()) {
                    return Err(GraphError::ReleaseSelectionInvalid {
                        package: id.clone(),
                        reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
                    });
                }
                prepared.insert(
                    operation.id().clone(),
                    PreparedOperation::RegistryPublish {
                        package_dir: package_dir(package)?,
                        package_name: id.name().to_string(),
                        version: version.clone(),
                        registry: binding,
                        npm_access: match target {
                            PublishTarget::Npm { access, .. } => *access,
                            _ => None,
                        },
                        npm_tag: matches!(target, PublishTarget::Npm { .. })
                            .then(|| version.is_prerelease().then_some("next".to_string()))
                            .flatten(),
                    },
                );
                publishes.push(operation.id().clone());
                operations.insert(operation.id().clone(), operation);
            }
        }
        publishes.sort();
        publishes_by_package.insert(id.clone(), publishes);
    }

    // Replace each publish leaf with prerequisites from selected dependency
    // packages. This preserves the existing publish semantics: runtime,
    // build, optional, and dev dependencies must exist before publish.
    for (id, (package, _)) in &selected {
        let mut prerequisites = BTreeSet::new();
        for edge in workspace.graph.dependencies_of(&package.id) {
            if !matches!(
                edge.kind,
                DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
            ) {
                continue;
            }
            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
                prerequisites.extend(
                    publishes_by_package
                        .get(dependency_release_id)
                        .into_iter()
                        .flatten()
                        .cloned(),
                );
            }
        }
        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
            let operation = operations.get(publish_id).expect("publish operation was constructed");
            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.iter().cloned().collect())?;
            operations.insert(publish_id.clone(), replacement);
        }
    }

    for (id, (package, version)) in &selected {
        if !package
            .publish_to
            .iter()
            .any(|target| !matches!(target, PublishTarget::None))
        {
            continue;
        }
        let tag = ReleaseOperation::tag(
            id.clone(),
            version.clone(),
            publishes_by_package.get(id).cloned().unwrap_or_default(),
        )?;
        let tag_name = package
            .tag_template
            .clone()
            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
            .render(version);
        let target = match &source {
            SourceIdentity::GitCommit { sha } => sha.clone(),
            SourceIdentity::HermeticContent { .. } => {
                return Err(GraphError::UnsupportedRelease {
                    feature: UnsupportedReleaseFeature::SourceIdentity,
                })
            }
        };
        prepared.insert(
            tag.id().clone(),
            PreparedOperation::Tag {
                annotation: format!("Release {tag_name}"),
                name: tag_name,
                target,
            },
        );
        tag_by_package.insert(id.clone(), tag.id().clone());
        operations.insert(tag.id().clone(), tag);
    }
    for (id, (package, version)) in &selected {
        if package
            .publish_to
            .iter()
            .any(|target| matches!(target, PublishTarget::GitHubRelease))
        {
            let tag = tag_by_package.get(id).expect("release point has tag").clone();
            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])?;
            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
                Some(PreparedOperation::Tag { name, .. }) => name.clone(),
                _ => {
                    return Err(GraphError::ReleaseInvariant {
                        detail: format!(
                            "forge release `{:?}` prerequisite is not a prepared Tag operation",
                            operation.id()
                        ),
                    })
                }
            };
            prepared.insert(operation.id().clone(), PreparedOperation::ForgeRelease { tag });
            operations.insert(operation.id().clone(), operation);
        }
    }

    Ok((
        ReleaseInputSnapshotV1::new(source, package_inputs)?,
        canonical_operation_order(operations)?,
        prepared,
        git_remote,
    ))
}

